  for var i := 0 to numbers.Length - 1 do
  begin
    res[i * 2] := numbers[i];
    if i <> numbers.Length - 1 then
    begin
      res[i * 2 + 1] := delimeter;
    end;
  end;
  Result := res;
end;


function ParseNestedParens(parenString: string): array of integer;
begin
  var maxDepth := 0;
  var currentDepth := 0;
  var stack := new Stack<integer>;
  var resultList := new List<integer>;
  foreach var ch in parenString do
  begin
    if ch = '(' then
    begin
      stack.Push(currentDepth);
      currentDepth += 1;
      if currentDepth > maxDepth then
        maxDepth := currentDepth;
    end
    else if ch = ')' then
    begin
      currentDepth -= 1;
      resultList.Add(stack.Pop());
    end;
  end;
  SetLength(resultList, stack.Count);
  for var i := stack.Count - 1 downto 0 do
    resultList[i] := stack.Pop();
  Result := resultList.ToArray();
end;


