function FindClosestElements(numbers: array of real): (real, real);
begin
  if numbers.Length < 2 then
    raise new System.ArgumentException('Array must contain at least two elements');
  var sortedNumbers := numbers.ToList;
  sortedNumbers.Sort;
  var minDiff := real.MaxValue;
  var resultTuple := (real.MaxValue, real.MaxValue);
  for var i := 0 to sortedNumbers.Count - 2 do
  begin
    if sortedNumbers[i] <> sortedNumbers[i + 1] then
    begin
      var currentDiff := sortedNumbers[i + 1] - sortedNumbers[i];
      if currentDiff < minDiff then
      begin
        minDiff := currentDiff;
        resultTuple := (sortedNumbers[i], sortedNumbers[i + 1]);
      end;
    end;
  end;
  Result := resultTuple;
end;


function RescaleToUnit(numbers: array of real): array of real;
begin
