function Factorize(n: integer): array of integer;
begin
  var i := 2;
  var factors := new List<integer>;
  var num := n;
  while i * i <= n do
  begin
    if n mod i = 0 then
    begin
      factors.Add(i);
      n := n div i;
    end
    else
      i += 1;
  end;
  if n > 1 then
    factors.Add(n);
  Result := factors.ToArray;
end;


