function EncodeCyclic(s : string): string;
{ returns encoded string by cycling groups of three characters. }
begin
  var groups := new List<string>;
  var i := 0;
  while i < s.Length do
  begin
    var group_length := Min(3, s.Length - i);
    groups.Add(s.Substring(i, group_length));
    i += 3;
  end;
  for var j := 0 to groups.Count - 1 do
  begin
    if groups[j].Length = 3 then
      groups[j] := groups[j].Substring(1, 2) + groups[j][1];
  end;
  Result := string.Join('', groups.ToArray);
end;
function DecodeCyclic(s: string): string;
begin
  var groups := new List<string>;
  var i := 0;
  while i < s.Length do
  begin
    var group_length := Min(3, s.Length - i);
    groups.Add(s.Substring(i, group_length));
    i += 3;
  end;

  for var j := 0 to groups.Count - 1 do
  begin
    if groups[j].Length = 3 then
      groups[j] := groups[j].Substring(1, 2) + groups[j][0];
  end;

  Result := string.Join('', groups.ToArray);
end;


function PrimeFib(n: integer): integer;

  function IsPrime(num: integer): boolean;
  begin
    if num < 2 then
      Result := False
    else
    begin
      for var i := 2 to Round(Sqrt(num)) do
        if num mod i = 0 then
        begin
          Result := False;
          exit;
        end;
      Result := True;
    end;
  end;

  function Fibonacci(n: integer): integer;
  begin
    if n = 0 then
      Result := 0
    else if n = 1 then
      Result := 1
    else
      Result := Fibonacci(n - 1) + Fibonacci(n - 2);
  end;

begin
  var count := 0;
  var i := 1;
  while count < n do
  begin
    var fib := Fibonacci(i);
    if fib > 1 then
    begin
      if IsPrime(fib) then
      begin
        count := count + 1;
        Result := fib;
      end
      else
        i := i + 1;
    end
    else
      i := i + 1;
  end;
end;


function TriplesSumToZero(l: array of integer): boolean;
begin
  var sortedList := l.ToList;
  sortedList.Sort;
  for var i := 0 to sortedList.Count - 3 do
  begin
    var left := i + 1;
    var right := sortedList.Count - 1;
    while left < right do
    begin
      var sum := sortedList[i] + sortedList[left] + sortedList[right];
      if sum = 0 then
      begin
        Result := true;
        exit;
      end
      else if sum < 0 then
        left += 1
      else
        right -= 1;
    end;
  end;
  Result := false;
end;


