  if x < 0 then
    raise new System.ArgumentException('Input number must be non-negative');
  var digits := '01123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ';
  if base < 10 then
    exit(digits[x mod base]);
  var res := '';
  while x > 0 do
  begin
    res := digits[x mod base] + res;
    x := x div base
  end;
  Result := res
end;


