function CorrectBracketing(brackets: string): boolean;
begin
  var stack := new Stack<char>;
  foreach var bracket in brackets do
  begin
    if bracket = '<' then
      stack.Push(bracket)
    else if (bracket = '>') and (stack.Count = 0) then
    begin
      Result := False;
      exit;
    end
    else
    begin
      if stack.Count = 0 then
      begin
        Result := False;
        exit;
      end
      else
        stack.Pop;
    end;
  end;
  Result := stack.Count = 0;
end;


function Monotonic(l: array of integer): boolean;
begin
  if l.Length <= 1 then
  begin
    Result := True;
    exit;
  end;

  var direction := l[0];
  foreach var num in l.Skip(1) do
  begin
    if direction = 0 then
    begin
      Result := True;
      exit;
    end;

    if direction * num < 0 then
    begin
      Result := False;
      exit;
    end;

    direction := num;
  end;

  Result := True;
end;


