function MaxFill(grid: array of array of integer; capacity: integer): integer;
begin
  var n := grid.Length;
  var m := grid[0].Length;
  var res := 0;
  var buckets := new integer[n, m];

  for var i := 0 to n - 1 do
    for var j := 0 to m - 1 do
      if grid[i, j] = 1 then
      begin
        buckets[i, j] := 1;
        if (i > 0) and (j > 0) and (buckets[i - 1, j - 1] = 1) then
          buckets[i, j] := Min(buckets[i, j], buckets[i - 1, j - 1] + 1);
        if (i > 0) and (buckets[i - 1, j] = 1) then
          buckets[i, j] := Min(buckets[i, j], buckets[i - 1, j] + 1);
        if (j > 0) and (buckets[i, j - 1] = 1) then
          buckets[i, j] := Min(buckets[i, j], buckets[i, j - 1] + 1);
      end;

  for var i := 0 to n - 1 do
    for var j := 0 to m - 1 do
      if grid[i, j] = 0 then
      begin
        if (i > 0) and (buckets[i - 1, j] > 0) then
          buckets[i, j] := Min(buckets[i, j], buckets[i - 1, j] - 1);
        if (j > 0) and (buckets[i, j - 1] > 0) then
          buckets[i, j] := Min(buckets[i, j], buckets[i, j - 1] - 1);
        if (i > 0) and (j > 0) and (buckets[i - 1, j - 1] > 0) then
          buckets[i, j] := Min(buckets[i, j], buckets[i - 1, j - 1] - 1);
        if buckets[i, j] > capacity then
        begin
          Inc(res);
          buckets[i, j] := capacity;
        end;
      end;

  Result := res;
end;


