  var bestDistance := MaxInt;
  var bestVowel := '';

  for var i := word.Length - 1 downto 0 do
  begin
    if not vowels.Contains(word[i]) then
    begin
      if (lastConsonantPos <> -1) and (i - lastConsonantPos < bestDistance) then
      begin
