    Result := False
  else
  begin
    var mm := StrToInt(parts[0]);
    var dd := StrToInt(parts[1]);
    var yyyy := StrToInt(parts[2]);

    if (mm < 1) or (mm > 12) then
      Result := False
    else if (dd < 1) or (dd > 31) then
      Result := False
    else if (mm = 2) then
    begin
      if dd > 29 then
        Result := False
      else if (dd = 29) and not (yyyy mod 4 = 0) then
        Result := False
    end
    else if (mm in [4, 6, 9, 11]) then
    begin
      if dd > 30 then
        Result := False
      else if (dd = 30) and not (mm mod 2 = 0) then
        Result := False
    end
    else
      Result := True;
  end;
end;


