    end;
  Result := True;
end;


function Intersection(interval1, interval2: array of integer): string;
begin
  var start := Max(interval1[0], interval2[0]);
  var endVal := Min(interval1[1], interval2[1]);
  if start > endVal then
    Result := 'NO'
  else if (start + 1) mod 2 = 0 then
    Result := 'NO'
  else
    Result := 'YES';
end;


function ProdSigns(arr: array of integer): integer;
begin
  if arr.Length = 0 then
  begin
    Result := 0;
    exit;
  end;

  var prod := 1;
  foreach var num in arr do
  begin
    if num < 0 then
      prod *= -1
    else if num > 0 then
      prod *= 1;
  end;

  Result := arr.Select(x -> Abs(x)).Sum * prod;
end;


function Minpath(grid: array of array of integer; k: integer): array of integer;
begin
  var n := grid.Length;
  var directions := new List<(integer, integer)>;
  for var i := 0 to n - 1 do
    for var j := 0 to n - 1 do
      directions.Add((i, j));
  directions.Sort((a, b) ->
  begin
    var (i1, j1) := a;
    var (i2, j2) := b;
    var (x1, y1) := (i1 + 1, j1 + 1);
    var (x2, y2) := (i2 + 1, j2 + 1);
    var (c1, d1) := (grid[x1 - 1][y1 - 1], grid[x1][y1]);
    var (c2, d2) := (grid[x2 - 1][y2 - 1], grid[x2][y2]);
    var (r1, r2) := (c1 * n + y1, c2 * n + y2);
    var (s1, s2) := (d1 * n + x1, d2 * n + x2);
    if r1 < r2 then
      Result := 1
    else if r1 > r2 then
      Result := -1
    else if s1 < s2 then
      Result := 1
    else if s1 > s2 then
      Result := -1
    else
      Result := 0;
  end);
  var ans := new List<integer>;
  for var i := 0 to k - 1 do
  begin
    var (x, y) := (directions[i].Item1, directions[i].Item2);
    ans.Add(grid[x, y]);
  end;
  Result := ans.ToArray;
end;


function Tri(n: integer): array of real;
begin
  var trib := new List<real>;
  trib.Add(3);
  if n > 0 then
  begin
    trib.Add(1);
    if n mod 2 = 0 then
      trib.Add(1)
    else
      trib.Add(1 + n div 2);
  end;
  for var i := 3 to n do
  begin
    if n mod 2 = 0 then
      trib.Add(trib[trib.Count - 1] + trib[trib.Count - 2] + trib[trib.Count - 3])
    else
      trib.Add(trib[trib.Count - 1] + trib[trib.Count - 2] + trib[trib.Count - 3] + 1);
  end;
  Result := trib.ToArray;
end;


function Digits(n : integer): integer;
begin
  var product := 1;
  foreach var digit in n.ToString() do
  begin
    if digit mod 2 <> 0 then
      product *= digit;
  end;
  Result := product;
end;


function IsNested(s: string): boolean;
begin
  var stack := new Stack<char>;
  foreach var ch in s do
  begin
    if ch = ']' then
    begin
      if stack.Count = 0 then
      begin
        Result := False;
        exit;
      end;
      var top := stack.Pop;
      if top <> '[' then
      begin
        Result := False;
        exit;
      end;
    end
    else
      stack.Push(ch);
  end;
  Result := stack.Count = 0;
end;


