function CanArrange(arr: array of integer): integer;
begin
  var n := arr.Length;
  var maxIndex := -1;
  var maxVal := arr[n - 1];
  for var i := n - 2 downto 0 do
  begin
    if arr[i] >= maxVal then
    begin
      maxIndex := i;
      maxVal := arr[i];
    end;
  end;
  Result := maxIndex;
end;


function LargestSmallestIntegers(lst: array of integer): (integer, integer);
