function IsEqualToSumEven(n: integer): boolean;
begin
  if n mod 2 <> 0 then
    Result := False
  else
  begin
    var a := 2;
    var b := 4;
    var c := 2;
    var d := 2;
    var sum := a + b + c + d;
    while a < n do
    begin
      if (n - sum) mod 2 = 0 then
      begin
        Result := True;
        exit;
      end
      else
      begin
        a := a + b;
        b := c;
        c := d;
        d := d + b;
        sum := a + b + c + d;
      end;
    end;
    Result := False;
  end;
end;


function SpecialFactorial(n: integer): integer;
begin
