function FixSpaces(text: string): string;
begin
  var newText := '';
  var spaces := 0;
  foreach var ch in text do
  begin
    if ch = ' ' then
    begin
      spaces += 1;
      if spaces = 1 then
        newText += ch
      else if spaces = 2 then
        newText += '-'
      else
        newText += '_';
    end
    else
    begin
      newText += ch;
      spaces := 0;
    end;
  end;
  Result := newText;
end;


function FileNameCheck(fileName: string): string;
begin
  var parts := fileName.Split('.');
  if parts.Length <> 2 then
    Result := 'No'
  else
  begin
    var nameParts := parts[0].Split(' ', System.StringSplitOptions.RemoveEmptyEntries);
    if nameParts.Length <> 1 then
      Result := 'No'
    else if nameParts[0].Length > 3 then
      Result := 'No'
    else if not (nameParts[0][0].IsLetter) then
      Result := 'No'
    else if not (nameParts[0][0].IsLower) then
      Result := 'No'
    else if not (nameParts[0][0].IsUpper) then
      Result := 'No'
    else
    begin
      var allowedExtensions := new HashSet<string>(['txt', 'exe', 'dll']);
      if not allowedExtensions.Contains(parts[1]) then
        Result := 'No'
      else
        Result := 'Yes';
    end;
  end;
end;


function SumSquares(lst: array of integer): integer;
