  var (numn, denn) := (integer(n.Substring(0, n.Index('/'))), integer(n.Substring(n.Index('/') + 1)));
  Result := (numx * denn) mod denx = 0;
end;


function OrderByPoints(nums: array of integer): array of integer;
begin
  var sortedNums := nums.OrderBy(x -> x.ToString.Sum(c -> StrToInt(c.ToString))).ToArray();
  var res := new List<integer>;
  for var i := 0 to nums.Length - 1 do
  begin
    var count := 0;
    while nums[i] mod 10 = 0 do
    begin
      count += 1;
      nums[i] := nums[i] div 10;
    end;
    res.Add(sortedNums[count * (sortedNums.Length - 1) + i]);
  end;
  Result := res.ToArray();
end;


