  var a := new integer[n];
  for var i := 0 to n - 1 do
    a[i] := i * i - i + 1;
  var res := 0;
  for var i := 0 to n - 1 do
    for var j := i + 1 to n - 1 do
      for var k := j + 1 to n - 1 do
        if (a[i] + a[j] + a[k]) mod 3 = 0 then
          res += 1;
  Result := res;
end;


function Bf(planet1, planet2: string): array of string;
begin
  var planets := new Dictionary<string, string>;
  planets['Mercury'] := 'Venus';
  planets['Venus'] := 'Earth';
  planets['Earth'] := 'Mars';
  planets['Mars'] := 'Jupiter';
  planets['Jupiter'] := 'Saturn';
  planets['Saturn'] := 'Uranus';
  planets['Uranus'] := 'Neptune'];

  if (not planets.ContainsKey(planet1)) or (not planets.ContainsKey(planet2)) then
  begin
    Result := #();
    exit;
  end;

  var path1 := new List<string>;
  var current := planet1;
  while current <> 'Mercury' do
  begin
    path1.Add(current);
    current := planets[current];
  end;
  path1.Add('Mercury');

  var path2 := new List<string>;
  current := planet2;
  while current <> 'Mercury' do
  begin
    path2.Add(current);
    current := planets[current];
  end;
  path2.Add('Mercury');

  Result := path1.Concat(path2).OrderBy(p -> path1.IndexOf(p) + path2.IndexOf(p)).ToArray();
end;


