function EvenOddCount(num: integer): (integer, integer);
begin
  var evenCount := 0;
  var oddCount := 0;
  var numStr := Abs(num);

  while numStr > 0 do
  begin
    var digit := numStr mod 10;
    if digit mod 2 = 0 then
      evenCount += 1
    else
      oddCount += 1;
    numStr := numStr div 10;
  end;

  Result := (evenCount, oddCount);
end;


function IntToMiniRoman(number: integer): string;
begin
  var roman := '';
  var num := number;
  while num >= 1000 do
  begin
    roman += 'm';
    num -= 1000;
  end;
  if num >= 900 then
  begin
    roman += 'cm';
    num -= 900;
  end;
  while num >= 90 do
  begin
    roman += 'c';
    num -= 90;
  end;
  while num >= 50 do
  begin
    roman += 'l';
    num -= 50;
  end;
  if num >= 40 then
  begin
    roman += 'xl';
    num -= 40;
  end;
  while num >= 10 do
  begin
    roman += 'x';
    num -= 10;
  end;
  while num >= 9 do
  begin
    roman += 'i';
    num -= 9;
  end;
  while num >= 5 do
  begin
    roman += 'v';
    num -= 5;
  end;
  if num >= 4 then
  begin
    roman += 'iv';
    num -= 4;
  end;
  while num >= 1 do
  begin
    roman += 'i';
    num -= 1;
  end;
  Result := roman;
end;


