  var maxWord := '';
  foreach var word in words do
  begin
    var uniqueCount := word.Distinct.Count;
    if uniqueCount > maxUnique then
    begin
      maxUnique := uniqueCount;
      maxWord := word;
    end;
  end;
  Result := maxWord;
end;


function Eat(number, need, remaining: integer): (integer, integer);
begin
  var eaten := Min(need, remaining) - number;
  Result := (number + eaten, remaining - eaten);
end;


function DoAlgebra(op: array of string; operand: array of integer): integer;
begin
  var s := operand[0].ToString;
  for var i := 1 to operand.Length - 1 do
  begin
    var op1 := op[i-1];
    s := s + ' ' + op1 + ' ' + operand[i].ToString;
    var arg1 := StrToInt(operand[i].ToString);
    var arg2 := operand[i+1];
    if op1 = '+' then
      s := s + ' + ' + arg2.ToString
    else if op1 = '-' then
      s := s + ' - ' + arg2.ToString
    else if op1 = '*' then
      s := s + ' * ' + arg2.ToString
    else if op1 = '//' then
      s := s + ' div ' + arg2.ToString
    else if op1 = '**' then
      s := s + ' ** ' + arg2.ToString;
    if op1 = '+' then
      arg2 := arg1 + arg2
    else if op1 = '-' then
      arg2 := arg1 - arg2
    else if op1 = '*' then
      arg2 := arg1 * arg2
    else if op1 = '//' then
      arg2 := arg1 div arg2
    else if op1 = '**' then
      arg2 := arg1 ** arg2;
  end;
  var v := &System.Convert.ToInt32(s);
  Result := v;
end;


function Solve(s: string): string;
begin
  var letters := new List<char>;
  var digits := new List<char>;
  var specials := new List<char>;

  foreach var ch in s do
  begin
    if ch.IsLetter then
      letters.Add(ch)
    else if ch.IsDigit then
      digits.Add(ch)
    else
      specials.Add(ch);
  end;

  var lettersList := letters.ToArray;
  var digitsList := digits.ToArray;
  var specialsList := specials.ToArray;

  var res := new List<char>;

  var i := 0;
  var j := 0;
  var k := 0;

  while (i < lettersList.Length) or (j < digitsList.Length) or (k < specialsList.Length) do
  begin
    if (i < lettersList.Length) and (j < digitsList.Length) and (k < specialsList.Length) then
    begin
      if (not lettersList[i].IsLower) and (not lettersList[i].IsUpper) then
      begin
        res.Add(lettersList[i]);
        i += 1;
      end
      else if (not lettersList[i].IsUpper) and (not lettersList[i].IsLower) then
      begin
        res.Add(lettersList[i]);
        i += 1;
      end
      else
      begin
        if lettersList[i].IsLower then
          res.Add(lettersList[i].ToUpper)
        else
          res.Add(lettersList[i].ToLower);
        i += 1;
      end;
    end
    else if (i < lettersList.Length) and (j < digitsList.Length) and (k >= specialsList.Length) then
    begin
      res.Add(lettersList[i]);
      i += 1;
    end
    else if (j < digitsList.Length) and (i >= lettersList.Length) and (k < specialsList.Length) then
    begin
      res.Add(digitsList[j]);
      j += 1;
    end
    else
    begin
      res.Add(specialsList[k]);
      k += 1;
    end;
  end;

  Result := new string(res.ToArray);
end;


function StringToMd5(text: string): string;
begin
  if text = '' then
  begin
    Result := '';
    exit;
  end;
  var h := new System.Security.Cryptography.MD5CryptoServiceProvider;
  var m := new System.Text.StringBuilder;
  var b := h.ComputeHash(System.Text.Encoding.UTF8.GetBytes(text));
  foreach var i in b do
    m.Append(i.ToString('x2'));
  Result := m.ToString;
end;


function GenerateIntegers(a, b: integer): array of integer;
begin
  var res := new List<integer>;
  for var i := a to b do
    if i mod 2 = 0 then
      res.Add(i);
  Result := res.ToArray;
end;
